# The storefront used to print emoji; it now draws stroke icons from the sprite.
EMOJI_TO_KEY = {
    "💻": "laptop",
    "🖥": "desktop",
    "🔧": "chip",
    "🎮": "gamepad",
    "📚": "book",
    "💼": "briefcase",
    "🎨": "palette",
    "🎬": "film",
    "⌨": "code",
}


def emoji_to_keys(apps, schema_editor):
    """Turn old emoji into icon keys; anything else becomes «auto»."""
    for model_name in ("category", "usecase"):
        Model = apps.get_model("catalog", model_name)
        for emoji, key in EMOJI_TO_KEY.items():
            Model.objects.filter(icon__in=(emoji, f"{emoji}\ufe0f")).update(icon=key)
        allowed = {value for value, _ in Model._meta.get_field("icon").choices}
        Model.objects.exclude(icon__in=allowed).update(icon="")


